'use strict';
const $=id=>document.getElementById(id),N=Net,KEY='cidr-studio-inventory-v2';
let plan={version:2,base:'10.0.0.0/24',allocations:[]},selected=null,page=0,history=[],suggestion=null;
const uid=()=>globalThis.crypto?.randomUUID?.()||Date.now().toString(36)+Math.random().toString(36).slice(2);
function notify(text,error=false){$('message').textContent=text;$('message').className=error?'error':''}
function safely(fn){try{fn()}catch(e){notify(e.message,true)}}
function element(tag,text,cls){const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(cls)e.className=cls;return e}
function button(text,fn,cls){const b=element('button',text,cls);b.type='button';b.onclick=()=>safely(fn);return b}
function commit(next,text,selectId=selected){const clean=N.validate(next);history.push(JSON.stringify(plan));if(history.length>30)history.shift();plan=clean;selected=clean.allocations.some(a=>a.id===selectId)?selectId:clean.allocations[0]?.id||null;page=0;suggestion=null;render();notify(text);}
function copy(){return JSON.parse(JSON.stringify(plan))}
function persist(){try{localStorage.setItem(KEY,JSON.stringify(plan));$('storageNote')?.remove()}catch{document.querySelector('.header-note').textContent='Storage unavailable · Export to save'}}
function choose(id){selected=id;page=0;render()}
function rangeText(r){return N.ip(r.start)+(r.end===r.start?'':' – '+N.ip(r.end))}
function reserve(cidr,name='Reserved subnet'){const next=copy(),id=uid();next.allocations.push({id,cidr,name,ips:[]});commit(next,'Subnet reserved. Track its occupied IPs below.',id)}
function drawRecommendation(){const out=$('recommendation');out.replaceChildren();if(!suggestion)return;const box=element('div',undefined,'result'+(suggestion.found?'':' fail'));if(suggestion.found){box.append(element('strong',suggestion.found.cidr),element('p',N.size(suggestion.p).toLocaleString()+' addresses · '+rangeText(suggestion.found)),button('Reserve this subnet',()=>reserve(suggestion.found.cidr,$('subnetName').value.trim()||'New subnet'),'primary'));}else{box.append(element('strong','No suitable /'+suggestion.p),element('p','There is no free, aligned subnet large enough for this request.'));const blocks=N.toCidrs(N.free(plan)).sort((a,b)=>a.p-b.p);box.append(element('p',blocks.length?'Largest available: '+blocks[0].cidr+'. Total free addresses may be split across smaller blocks.':'The parent network is fully reserved.'))}out.append(box)}
function render(){const base=N.parse(plan.base),free=N.free(plan),blocks=N.toCidrs(free),freeCount=free.reduce((s,r)=>s+r.end-r.start+1,0),all=N.size(base.p),reserved=all-freeCount;persist();$('base').value=plan.base;$('rootLabel').textContent=plan.base;$('reserved').textContent=reserved.toLocaleString();$('free').textContent=freeCount.toLocaleString();$('largest').textContent=blocks.length?'/'+Math.min(...blocks.map(b=>b.p)):'None';$('usage').textContent=(reserved/all*100).toFixed(1)+'% reserved';$('axisStart').textContent=N.ip(base.start);$('axisEnd').textContent=N.ip(base.end);$('undo').disabled=!history.length;$('badge').textContent=plan.allocations.length;$('freeCount').textContent=blocks.length+' BLOCKS';$('empty').textContent=plan.allocations.length?'':'No reservations yet. Add an existing subnet or load the example.';
const parts=[...free.map(r=>({...r,free:true})),...plan.allocations.map(a=>({...N.parse(a.cidr),allocation:a}))].sort((a,b)=>a.start-b.start);$('landscape').replaceChildren(...parts.map(r=>{const label=r.free?'Free: '+rangeText(r):r.allocation.name+': '+r.allocation.cidr;const b=button('',()=>{if(r.allocation)choose(r.allocation.id);else{$('subnet').value=N.toCidrs([r])[0].cidr;$('subnet').focus();notify('Free block selected. Reserve it below, or request a smaller subnet.')}},r.free?'':'taken');b.style.width=((r.end-r.start+1)/all*100)+'%';b.title=label;b.setAttribute('aria-label',label);b.setAttribute('aria-pressed',String(!!r.allocation&&r.allocation.id===selected));if((r.end-r.start+1)/all>.06)b.append(element('span',r.free?'FREE':'/'+r.p));return b}));
$('mapcards').replaceChildren(...plan.allocations.map(a=>{const b=button('',()=>choose(a.id),'mapcard'+(selected===a.id?' active':''));b.append(element('span',a.name,'name'),element('strong',a.cidr),element('small',a.ips.length+' occupied IPs tracked'));return b}));
$('freeBlocks').replaceChildren(...blocks.map(b=>{const el=button(b.cidr,()=>{$('subnet').value=b.cidr;$('subnet').focus();notify('Free block selected. Use Reserve subnet to allocate it.')});el.title=N.size(b.p).toLocaleString()+' addresses';return el}));if(!blocks.length)$('freeBlocks').append(element('p','No unallocated address space.','aside-note'));
$('rows').replaceChildren(...plan.allocations.map(a=>{const tr=element('tr',undefined,a.id===selected?'active':'');const first=element('td'),select=button('',()=>choose(a.id));select.append(element('strong',a.name),element('small',a.cidr));first.append(select);const r=N.usableRange(N.parse(a.cidr)),count=r.end-r.start+1;const actions=element('td');actions.append(button('Remove',()=>{const next=copy();next.allocations=next.allocations.filter(x=>x.id!==a.id);commit(next,'Subnet removed. Undo is available.')}));tr.append(first,element('td',String(a.ips.length)),element('td',(count-a.ips.length).toLocaleString()),actions);return tr}));drawRecommendation();renderInspector();}
function renderInspector(){const a=plan.allocations.find(x=>x.id===selected);$('inspector').hidden=!a;if(!a)return;const r=N.parse(a.cidr),usable=N.usableRange(r),used=new Set(a.ips.map(N.number)),free=N.subtract(usable,[...used].map(start=>({start,end:start}))),count=usable.end-usable.start+1-used.size;$('selectedTitle').textContent=a.name+' · '+a.cidr;$('selectedRange').textContent=rangeText(r)+' · mask '+N.ip(2**32-N.size(r.p));$('ipStats').textContent=used.size+' occupied · '+count.toLocaleString()+' free hosts';$('ips').value=a.ips.join('\n');$('hostRanges').replaceChildren(...free.map(x=>element('div',rangeText(x))));if(!free.length)$('hostRanges').append(element('div','No free host addresses.'));const pages=Math.ceil(N.size(r.p)/256);page=Math.max(0,Math.min(page,pages-1));const start=r.start+page*256,end=Math.min(r.end,start+255);$('pageLabel').textContent=rangeText({start,end})+' · '+(page+1).toLocaleString()+'/'+pages.toLocaleString();$('prev').disabled=page===0;$('next').disabled=page===pages-1;const cells=[];for(let n=start;n<=end;n++){const system=n<usable.start||n>usable.end,b=button(String(n%256),()=>{const next=copy(),record=next.allocations.find(x=>x.id===selected),text=N.ip(n);record.ips=used.has(n)?record.ips.filter(x=>x!==text):[...record.ips,text];const keepPage=page;commit(next,text+(used.has(n)?' marked free.':' marked occupied.'));page=keepPage;renderInspector()},system?'system':used.has(n)?'used':'');b.disabled=system;const label=N.ip(n)+' · '+(system?(n===r.start?'Network address':'Broadcast address'):used.has(n)?'Occupied':'Free');b.title=label;b.setAttribute('aria-label',label);if(!system)b.setAttribute('aria-pressed',String(used.has(n)));cells.push(b)}$('ipGrid').replaceChildren(...cells)}
$('baseForm').onsubmit=e=>{e.preventDefault();safely(()=>{const base=N.parse($('base').value),next=copy();next.base=base.cidr;commit(next,'Parent network set to '+base.cidr+'. Existing reservations retained.');})};
$('addForm').onsubmit=e=>{e.preventDefault();safely(()=>{reserve($('subnet').value,$('subnetName').value.trim()||'Reserved subnet');$('subnet').value='';$('subnetName').value=''})};
$('bulkForm').onsubmit=e=>{e.preventDefault();safely(()=>{const next=copy();const lines=$('bulk').value.split(/\r?\n/).filter(x=>x.trim());if(!lines.length)throw Error('Enter at least one subnet.');for(const line of lines){const [cidr,...name]=line.split(',');next.allocations.push({id:uid(),cidr:cidr.trim(),name:name.join(',').trim()||'Reserved subnet',ips:[]})}commit(next,lines.length+' subnets reserved.');$('bulk').value=''})};
$('ipsForm').onsubmit=e=>{e.preventDefault();safely(()=>{const next=copy(),a=next.allocations.find(x=>x.id===selected);a.ips=$('ips').value.trim()?$('ips').value.trim().split(/[\s,;]+/):[];commit(next,'Occupied IP list saved.');})};
$('requestMode').onchange=()=>{const host=$('requestMode').value==='hosts';$('requestLabel').textContent=host?'Usable hosts required':'Prefix length (0–32)';$('request').min=host?'1':'0';$('request').max=host?'4294967294':'32';$('request').value=host?'50':'26';suggestion=null;drawRecommendation()};$('request').oninput=()=>{suggestion=null;drawRecommendation()};
$('findForm').onsubmit=e=>{e.preventDefault();safely(()=>{const v=Number($('request').value),p=$('requestMode').value==='hosts'?N.prefixForHosts(v):v;const found=N.recommend(plan,p);suggestion={p,found};drawRecommendation();notify(found?'A free subnet is available. Reserve it to add it to the plan.':'No free subnet matches the requested size.',!found)})};
$('prev').onclick=()=>{page--;renderInspector()};$('next').onclick=()=>{page++;renderInspector()};$('jumpForm').onsubmit=e=>{e.preventDefault();safely(()=>{const r=N.parse(plan.allocations.find(a=>a.id===selected).cidr),n=N.number($('jump').value);if(n<r.start||n>r.end)throw Error('That IP is outside the selected subnet.');page=Math.floor((n-r.start)/256);renderInspector();notify('Showing '+N.ip(n))})};
$('undo').onclick=()=>{if(!history.length)return;plan=JSON.parse(history.pop());selected=plan.allocations[0]?.id||null;page=0;suggestion=null;render();notify('Last change undone.')};$('reset').onclick=()=>commit({...plan,allocations:[]},'Reservations cleared. Undo is available.');$('demo').onclick=()=>commit({version:2,base:'10.0.0.0/24',allocations:[{id:uid(),cidr:'10.0.0.0/26',name:'Production',ips:['10.0.0.1','10.0.0.10','10.0.0.11']},{id:uid(),cidr:'10.0.0.128/27',name:'Database',ips:['10.0.0.130','10.0.0.131']}]},'Example loaded. Your previous plan is available with Undo.');
function download(content,name,type){const u=URL.createObjectURL(new Blob([content],{type})),a=element('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
$('export').onclick=()=>download(JSON.stringify(plan,null,2),'cidr-studio-plan.json','application/json');$('import').onclick=()=>$('file').click();$('file').onchange=async()=>{const file=$('file').files[0];if(!file)return;try{if(file.size>5*1024*1024)throw Error('Plan file must be smaller than 5 MB.');const data=JSON.parse(await file.text());commit(data,'Plan imported.')}catch(e){notify('Import failed: '+e.message,true)}finally{$('file').value=''}};
$('csv').onclick=()=>{const escape=value=>'"'+String(value).replace(/^[=+@\-\t\r]/,"'$&").replace(/"/g,'""')+'"';const rows=[['Status','Name','CIDR','First address','Last address','Tracked occupied IPs'],...plan.allocations.map(a=>{const r=N.parse(a.cidr);return ['Reserved',a.name,a.cidr,N.ip(r.start),N.ip(r.end),a.ips.join('; ')]}),...N.toCidrs(N.free(plan)).map(r=>['Free','',r.cidr,N.ip(r.start),N.ip(r.end),''])];download(rows.map(r=>r.map(escape).join(',')).join('\r\n'),'cidr-studio-inventory.csv','text/csv;charset=utf-8')};
try{const stored=localStorage.getItem(KEY);if(stored)plan=N.validate(JSON.parse(stored));selected=plan.allocations[0]?.id||null}catch{notify('The saved plan could not be loaded. You can import a saved JSON plan.',true)}render();
